import {sampleSectionWeightCurve} from './sequence-weight-curve.js';
import {Euler,Quaternion,MathUtils} from 'three';

export const sequenceBlendModes=['override','normalized'];
export const validSequenceWeight=n=>Number.isFinite(n)&&n>=0&&n<=1;
export const validSequenceBlend=data=>(data.weight===undefined||validSequenceWeight(data.weight))&&(data.blendMode===undefined||sequenceBlendModes.includes(data.blendMode));
export const validSequenceSectionBlend=section=>(section.weight===undefined||validSequenceWeight(section.weight))&&(section.blendMode===undefined||section.blendMode==='inherit'||sequenceBlendModes.includes(section.blendMode));
export const sequenceBlendSettings=(data,parent,section)=>({weight:(parent?.weight??1)*(data.weight??1)*(section?.weight??1)*sampleSectionWeightCurve(section,parent?.time??section?.start??0),blendMode:section?.blendMode&&section.blendMode!=='inherit'?section.blendMode:data.blendMode??parent?.blendMode??'override'});
const weight=e=>e.owner.weight??1;
export const sequenceEntryEnabled=e=>!e.mix||e.owner.blendMode!=='normalized'||weight(e)>0;
const scalar=n=>typeof n==='number'&&Number.isFinite(n);
export const blendSequenceNumber=(a,b,t)=>t===0?a:t===1?b:(a>=0)===(b>=0)?a+(b-a)*t:a*(1-t)+b*t;
// Convex accumulation avoids overflowing (b-a) for opposite large finite values.
function linear(entries){let result=entries[0].value,total=weight(entries[0]);const vector=Array.isArray(result);if(!(vector?result.length>=2&&result.length<=4&&result.every(scalar):scalar(result)))throw Error('시퀀스 혼합 값은 유한한 수 또는 벡터여야 해요.');for(let i=1;i<entries.length;i++){const e=entries[i],v=e.value,next=total+weight(e),t=weight(e)/next;if(vector? !Array.isArray(v)||v.length!==result.length||!v.every(scalar):!scalar(v))throw Error('시퀀스 혼합 채널의 자료형이 달라요.');result=vector?result.map((n,k)=>blendSequenceNumber(n,v[k],t)):blendSequenceNumber(result,v,t);total=next;}return result;}
// Hemisphere-aligned quaternion sum: +179/-179 degrees blend around 180, not 0.
function rotation(entries){const q=new Quaternion(),reference=new Quaternion(),euler=new Euler(),sum=[0,0,0,0];let dominant=entries[0];for(const e of entries)if(weight(e)>weight(dominant))dominant=e;const maximum=weight(dominant);reference.setFromEuler(euler.set(...dominant.value.map(MathUtils.degToRad),'XYZ'));let total=0;for(let i=0;i<entries.length;i++){const e=entries[i],v=e.value;if(!Array.isArray(v)||v.length!==3||!v.every(scalar))throw Error('회전 혼합 값은 유한한 XYZ 각도여야 해요.');q.setFromEuler(euler.set(...v.map(MathUtils.degToRad),'XYZ'));const w=weight(e)/maximum*(q.dot(reference)<0?-1:1);sum[0]+=q.x*w;sum[1]+=q.y*w;sum[2]+=q.z*w;sum[3]+=q.w*w;total+=weight(e)/maximum;}q.fromArray(sum.map(v=>v/total)).normalize();euler.setFromQuaternion(q,'XYZ');return [euler.x,euler.y,euler.z].map(MathUtils.radToDeg);}
export function blendSequenceEntries(top,entries){if(!top.mix||top.owner.blendMode!=='normalized')return top.value;const peers=[top];for(const e of entries.values())if(e!==top&&e.mix===top.mix&&e.owner.blendMode==='normalized'&&(e.owner.priority??0)===(top.owner.priority??0)&&weight(e)>0)peers.push(e);if(peers.length===1)return top.value;if(typeof top.mix==='function')return top.mix(peers);return top.mix==='rotation'?rotation(peers):linear(peers);}
export const sequenceBlendContract={asset:'optional blendMode override|normalized and weight0..1; absent keeps legacy winner behavior; child mode inherits unless authored, effective child weight is parent weight times local asset weight times section weight; optional section blendMode inherit|override|normalized overrides child asset mode only when explicit',continuous:'opt-in normalized owners at the winning priority mix compatible continuous number/vector, per-bone skeletal TRS and managed animation-clip channels; each skeletal track poseWeight first blends against shared baseline, then competing layer weights normalize; strongest override owner is exclusive; normalized owners exclude override peers at the same priority; zero weight yields to the next eligible priority or shared baseline',rotation:'XYZ degrees converted to hemisphere-aligned unit quaternion weighted sum, normalized and converted back to XYZ; largest-weight sample is the hemisphere reference, with strongest sample breaking ties',discrete:'visibility, parent, camera, component presence, integer/enum/object/array values keep existing priority/start-order behavior; animation clips use compatible-family normalized weights when enabled, while sprite frames remain discrete within the winning family; weight does not mute events/audio or suspend simulation',control:'LevelSequence SetWeight/GetWeight and SetBlendMode/GetBlendMode; root override recomputes sampled descendant fields together without seek, events, resampling, new start order or asset mutation',completion:'removing any contributing owner immediately recomputes remaining normalized peers; final owner follows existing completion/forceRestore policy; all-zero active owners retain shared baseline leases',remaining:['independent Euler-axis layer composition and renderer aliases','renderer/component aliases beyond existing shared transform fields','asynchronous external setter rollback']};
